input.sparql:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX b: <https://brickschema.org/schema/Brick#>
PREFIX br: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?zoneLabel ?sensor ?tsid WHERE {
  ?sensor a b:Zone_Air_Temperature_Sensor .
  ?sensor b:isPointOf ?zone .
  OPTIONAL { ?sensor br:hasExternalReference ?ext . ?ext br:hasTimeseriesId ?tsid }
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
} LIMIT 200
